import { afterEach, describe, expect, it, vi } from "vitest";
// The Worker is intentionally standalone and uses only platform Web APIs.
// @ts-ignore standalone .mjs Worker is not generated by Next.js
import { handleRequest } from "../auth-worker/worker.mjs";

const origin = "https://ideadock-auth.example.workers.dev";
const api = `${origin}/IdeaDock/api/auth`;
const scope = "https://www.googleapis.com/auth/drive.file";

function fakeEnv() {
  const records = new Map<string, Record<string, unknown>>();
  let assetPath = "";
  const db = {
    prepare(statement: string) {
      return {
        bind(...args: unknown[]) {
          return {
            async first() {
              const record = records.get(String(args[0]));
              if (statement.startsWith("SELECT access_expires")) return record ? { access_expires: record.access_expires } : null;
              if (statement.startsWith("SELECT *")) return record || null;
              throw new Error("Unexpected SELECT " + statement);
            },
            async run() {
              if (statement.startsWith("INSERT")) {
                const [sid_hash, google_sub, email, display_name, refresh_ciphertext, access_ciphertext, access_expires, session_expires, created_at] = args;
                records.set(String(sid_hash), { sid_hash, google_sub, email, display_name, refresh_ciphertext, access_ciphertext, access_expires, session_expires, created_at });
                return { meta: { changes: 1 } };
              }
              if (statement.startsWith("UPDATE auth_sessions SET access_ciphertext")) {
                const [access_ciphertext, refresh_ciphertext, access_expires, sid, previous] = args;
                const row = records.get(String(sid));
                if (!row || row.access_expires !== previous) return { meta: { changes: 0 } };
                Object.assign(row, { access_ciphertext, refresh_ciphertext, access_expires });
                return { meta: { changes: 1 } };
              }
              if (statement.startsWith("UPDATE auth_sessions SET session_expires")) {
                const [session_expires, sid] = args;
                const row = records.get(String(sid));
                if (row) row.session_expires = session_expires;
                return { meta: { changes: row ? 1 : 0 } };
              }
              if (statement.startsWith("DELETE")) {
                records.delete(String(args[0]));
                return { meta: { changes: 1 } };
              }
              throw new Error("Unexpected SQL " + statement);
            },
          };
        },
      };
    },
  };
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return {
    env: {
      GOOGLE_CLIENT_ID: "test-client.apps.googleusercontent.com",
      GOOGLE_CLIENT_SECRET: "test-value",
      SESSION_ENCRYPTION_KEY: Buffer.from(bytes).toString("base64"),
      APP_ORIGIN: origin,
      AUTH_DB: db,
      ASSETS: {
        async fetch(request: Request) {
          assetPath = new URL(request.url).pathname;
          return new Response("static", { status: 200 });
        },
      },
    },
    records,
    lastAsset: () => assetPath,
  };
}
function cookieValue(headers: Headers, name: string) {
  const all = typeof headers.getSetCookie === "function" ? headers.getSetCookie().join("; ") : (headers.get("set-cookie") || "");
  const match = all.match(new RegExp(`(?:^|[,;]\\s*)${name}=([^;,]*)`));
  if (!match) throw new Error(`Missing cookie ${name}: ${all}`);
  return match[1];
}
function mockedGoogle() {
  let tokenCalls = 0;
  const mock = vi.fn(async (input: string | Request, init?: RequestInit) => {
    const url = String(input);
    if (url.includes("oauth2.googleapis.com/token")) {
      tokenCalls++;
      const params = new URLSearchParams(String(init?.body || ""));
      if (params.get("grant_type") === "refresh_token") {
        return new Response(JSON.stringify({ access_token: "tok2", expires_in: 3600, scope }), { status: 200 });
      }
      if (params.get("grant_type") === "authorization_code") {
        expect(params.get("code_verifier")).toBeTruthy();
        return new Response(JSON.stringify({ access_token: "tok1", refresh_token: "server-only-refresh-token", expires_in: 3600, scope }), { status: 200 });
      }
    }
    if (url.includes("openidconnect.googleapis.com/v1/userinfo"))
      return new Response(JSON.stringify({ sub: "123456", email: "example@example.com", name: "Idea owner" }), { status: 200 });
    throw new Error(`Unexpected Google endpoint: ${url}`);
  });
  vi.stubGlobal("fetch", mock);
  return { tokenCalls: () => tokenCalls, mock };
}
async function login(env: ReturnType<typeof fakeEnv>["env"]) {
  const start = await handleRequest(new Request(`${api}/start`), env);
  expect(start.status).toBe(302);
  const url = new URL(start.headers.get("location")!);
  expect(url.origin).toBe("https://accounts.google.com");
  expect(url.searchParams.get("access_type")).toBe("offline");
  expect(url.searchParams.get("code_challenge_method")).toBe("S256");
  expect(url.searchParams.get("scope")).toContain(scope);
  const flow = cookieValue(start.headers, "__Host-ideadock-oauth");
  expect(flow).not.toContain("server-only-refresh-token");
  const callback = await handleRequest(new Request(
    `${api}/callback?state=${encodeURIComponent(url.searchParams.get("state")!)}&code=one-use-code`,
    { headers: { Cookie: `__Host-ideadock-oauth=${flow}` } },
  ), env);
  expect(callback.status).toBe(302);
  const sid = cookieValue(callback.headers, "__Host-ideadock-session");
  return { start, callback, sid, flow };
}
afterEach(() => { vi.unstubAllGlobals(); vi.restoreAllMocks(); });
describe("same-origin Cloudflare OAuth backend", () => {
  it("redirects Google through PKCE/state and keeps refresh tokens encrypted", async () => {
    const { env, records } = fakeEnv();
    mockedGoogle();
    const { callback, sid } = await login(env);
    expect(callback.headers.get("location")).toBe(`${origin}/IdeaDock/`);
    const cookies = callback.headers.getSetCookie().join(" ");
    expect(cookies).toMatch(/HttpOnly/);
    expect(cookies).toMatch(/SameSite=Lax/);
    expect(cookies).toMatch(/Secure/);
    expect(sid.length).toBeGreaterThan(40);
    expect(records.size).toBe(1);
    const saved = [...records.values()][0];
    expect(JSON.stringify(saved)).not.toContain("server-only-refresh-token");
    expect(JSON.stringify(saved)).not.toContain("tok1");
    expect(JSON.stringify(saved)).not.toContain(sid);
  });
  it("returns short-lived access credentials but never refresh tokens", async () => {
    const { env } = fakeEnv();
    mockedGoogle();
    const { sid } = await login(env);
    const response = await handleRequest(new Request(`${api}/session`, { headers: { Cookie: `__Host-ideadock-session=${sid}` } }), env);
    expect(response.status).toBe(200);
    const body = await response.json() as Record<string, any>;
    expect(body.authenticated).toBe(true);
    expect(body.user.id).toBe("google:123456");
    expect(body.token).toBe("tok1");
    expect(JSON.stringify(body)).not.toContain("refresh-token");
    expect(response.headers.get("cache-control")).toContain("no-store");
  });
  it("refreshes Google token without visiting the login screen", async () => {
    const { env, records } = fakeEnv();
    const google = mockedGoogle();
    const { sid } = await login(env);
    const record = [...records.values()][0];
    record.access_expires = 1;
    const response = await handleRequest(new Request(`${api}/session`, { headers: { Cookie: `__Host-ideadock-session=${sid}` } }), env);
    expect(response.status).toBe(200);
    const body = await response.json() as Record<string, any>;
    expect(body.token).toBe("tok2");
    expect(google.tokenCalls()).toBe(2);
  });
  it("rejects forged OAuth state and untrusted origins", async () => {
    const { env, records } = fakeEnv();
    mockedGoogle();
    const start = await handleRequest(new Request(`${api}/start`), env);
    const flow = cookieValue(start.headers, "__Host-ideadock-oauth");
    const forged = await handleRequest(new Request(`${api}/callback?state=forged&code=code`, {
      headers: { Cookie: `__Host-ideadock-oauth=${flow}` },
    }), env);
    expect(forged.status).toBe(400);
    expect(records.size).toBe(0);
    const badOrigin = await handleRequest(new Request("https://not-example.test/IdeaDock/api/auth/session"), env);
    expect(badOrigin.status).toBe(503);
  });
  it("requires same-origin POST to end the session", async () => {
    const { env, records } = fakeEnv();
    mockedGoogle();
    const { sid } = await login(env);
    const forbidden = await handleRequest(new Request(`${api}/logout`, {
      method: "POST", headers: { Origin: "https://attacker.example", Cookie: `__Host-ideadock-session=${sid}` },
    }), env);
    expect(forbidden.status).toBe(403);
    expect(records.size).toBe(1);
    const result = await handleRequest(new Request(`${api}/logout`, {
      method: "POST", headers: { Origin: origin, Cookie: `__Host-ideadock-session=${sid}` },
    }), env);
    expect(result.status).toBe(200);
    expect(records.size).toBe(0);
    expect(result.headers.get("set-cookie")).toContain("Max-Age=0");
  });
  it("serves Next.js exported assets from the same origin under /IdeaDock", async () => {
    const { env, lastAsset } = fakeEnv();
    const asset = await handleRequest(new Request(`${origin}/IdeaDock/_next/static/example.js`), env);
    expect(asset.status).toBe(200);
    expect(lastAsset()).toBe("/_next/static/example.js");
    await handleRequest(new Request(`${origin}/IdeaDock/`), env);
    expect(lastAsset()).toBe("/index.html");
  });
});
